:root {
  --bg: #040607; --panel: #0d1419; --panel-2: #121b22; --line: #24313a; --fg: #eef7f4; --muted: #84929c;
  --accent: #2ee8d6; --violet: #9f7cff; --pink: #ff4fd8; --verified: #36e39b; --self: #ffc64d; --err: #ff7768;
  --motion: cubic-bezier(.22,.68,.12,1);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; min-height: 100%; background: var(--bg); color: var(--fg);
  font: 15px/1.5 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; }
body { position: relative; overflow-x: hidden; }
body::before { content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background: linear-gradient(rgba(255,255,255,.026) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.018) 1px, transparent 1px),
    linear-gradient(180deg, transparent 0 48%, rgba(46,232,214,.055) 50%, transparent 52%);
  background-size: 100% 3px, 42px 42px, 100% 10px; opacity: .58; mix-blend-mode: screen; }
body::after { content: ""; position: fixed; inset: -20%; z-index: 0; pointer-events: none;
  background: conic-gradient(from 150deg at 18% 16%, rgba(46,232,214,.15), transparent 18%, rgba(255,79,216,.1) 34%, transparent 52%, rgba(255,198,77,.1) 70%, transparent 88%);
  animation: field-turn 18s var(--motion) infinite alternate; }
a { color: inherit; text-decoration: none; }
code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; background: #071014; color: #d9fff2;
  padding: 1px 6px; border: 1px solid rgba(46,232,214,.22); border-radius: 6px; }

.hdr { position: relative; z-index: 2; display: flex; align-items: center; justify-content: space-between;
  padding: 18px 24px; border-bottom: 1px solid color-mix(in srgb, var(--accent) 20%, var(--line));
  background: linear-gradient(90deg, rgba(4,6,7,.94), rgba(8,15,18,.84)); box-shadow: inset 0 -1px 0 rgba(255,255,255,.04); }
.brand { font: 900 20px/1 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: .02em; text-shadow: 0 0 24px rgba(54,227,155,.3); }
.brand span { color: var(--accent); }
.hdr nav { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; }
.hdr nav a { color: var(--muted); border: 1px solid transparent; border-radius: 999px; padding: 6px 9px;
  transition: color .38s var(--motion), border-color .38s var(--motion), transform .38s var(--motion); }
.hdr nav a:hover { color: var(--fg); border-color: color-mix(in srgb, var(--accent) 35%, transparent); transform: translateY(-1px); }
.app-shell-dock { position: relative; z-index: 2; max-width: 1120px; margin: 12px auto 0; padding: 0 24px;
  display: grid; grid-template-columns: minmax(300px, .82fr) minmax(0, 1.18fr); gap: 1px; }
.app-shell-dock__terminal, .app-shell-signals { border: 1px solid color-mix(in srgb, var(--accent) 20%, var(--line));
  background: rgba(5,8,10,.92); box-shadow: 0 26px 82px -70px var(--accent), inset 0 1px 0 rgba(255,255,255,.07); overflow: hidden; }
.app-shell-dock__terminal { position: relative; min-height: 214px; border-radius: 10px 0 0 10px; padding: 12px;
  background: radial-gradient(circle at 22% 0, rgba(46,232,214,.12), transparent 34%),
    repeating-linear-gradient(0deg, rgba(255,255,255,.035) 0 1px, transparent 1px 8px), #040708; }
.app-shell-dock__terminal::after { content: ""; position: absolute; left: 10px; right: 10px; top: 48px; height: 22px;
  background: linear-gradient(180deg, transparent, rgba(46,232,214,.14), rgba(255,198,77,.08), transparent);
  animation: terminal-scan 5.2s var(--motion) infinite; pointer-events: none; }
.app-shell-dock__terminal pre { position: relative; z-index: 1; margin: 0; color: #d9fff2; white-space: pre; overflow: auto;
  font: 900 9px/1.25 ui-monospace, SFMono-Regular, Menlo, monospace; text-shadow: 0 0 16px rgba(46,232,214,.2); }
.app-shell-dock__ticker { position: relative; z-index: 1; margin-top: 8px; overflow: hidden; white-space: nowrap;
  color: var(--self); font: 900 9px/1 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: .12em; }
.app-shell-marquee { position: relative; z-index: 1; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 1px;
  margin-top: 8px; border: 1px solid color-mix(in srgb, var(--self) 20%, rgba(255,255,255,.08)); border-radius: 8px;
  background: rgba(255,255,255,.07); overflow: hidden; }
.app-shell-marquee-step { --tone: var(--brand-from, var(--accent)); --tone-2: var(--brand-to, var(--verified)); --brand-ink: #071013;
  position: relative; min-height: 78px; display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 4px 7px; align-content: start;
  padding: 8px; background: linear-gradient(145deg, color-mix(in srgb, var(--tone) 12%, #0b1115), #040708); overflow: hidden;
  animation: feed-rise .46s var(--motion) both; animation-delay: calc(var(--i) * 54ms); }
.app-shell-marquee-step::before { content: ""; position: absolute; left: 0; bottom: 0; width: var(--meter); height: 2px;
  background: linear-gradient(90deg, var(--tone), var(--tone-2)); box-shadow: 0 0 18px color-mix(in srgb, var(--tone) 30%, transparent); }
.app-shell-marquee-step::after { content: ""; position: absolute; inset: 0;
  background: linear-gradient(114deg, transparent 0 39%, color-mix(in srgb, var(--tone) 15%, transparent) 49%, transparent 60%);
  transform: translateX(-94%); animation: passkey-sweep 5.2s var(--motion) infinite; animation-delay: calc(var(--i) * 130ms); pointer-events: none; }
.app-shell-marquee-step[data-impact="trust"] { border-left: 1px dashed color-mix(in srgb, var(--self) 48%, var(--line)); }
.app-shell-marquee-step[data-impact="local"] { border-left: 1px dashed color-mix(in srgb, var(--verified) 36%, var(--line)); }
.app-shell-marquee-step[data-impact="privacy"] { border-left: 1px dashed color-mix(in srgb, var(--pink) 44%, var(--line)); }
.app-shell-marquee-step[data-impact="publish"] { border-left: 1px dashed color-mix(in srgb, var(--accent) 34%, var(--line)); }
.app-shell-marquee-step > * { position: relative; z-index: 1; min-width: 0; }
.app-shell-marquee-step i { grid-row: span 2; display: inline-grid; place-items: center; width: 28px; height: 26px; border-radius: 8px;
  color: var(--brand-ink); background: linear-gradient(135deg, var(--tone), var(--tone-2)); font: 900 8.8px/1 ui-monospace, SFMono-Regular, Menlo, monospace; font-style: normal; }
.app-shell-marquee-step b { color: var(--self); font: 900 8px/1 ui-monospace, SFMono-Regular, Menlo, monospace; text-transform: uppercase; overflow-wrap: anywhere; }
.app-shell-marquee-step em { color: #f4fffb; font: 950 8.5px/1 ui-monospace, SFMono-Regular, Menlo, monospace; font-style: normal; text-transform: uppercase; overflow-wrap: anywhere; }
.app-shell-marquee-step small { grid-column: 1 / -1; color: #a8b7bd; font: 800 7.6px/1.22 ui-monospace, SFMono-Regular, Menlo, monospace; overflow-wrap: anywhere; }
.app-shell-dock__totals { position: relative; z-index: 1; display: flex; flex-wrap: wrap; gap: 5px; margin-top: 10px; }
.app-shell-dock__totals span { color: #d9fff2; border: 1px solid color-mix(in srgb, var(--accent) 26%, var(--line));
  border-radius: 999px; padding: 4px 6px; background: rgba(0,0,0,.22); font: 900 8px/1 ui-monospace, SFMono-Regular, Menlo, monospace; text-transform: uppercase; }
.app-shell-spectrum { position: relative; z-index: 1; margin-top: 10px; border: 1px solid color-mix(in srgb, var(--self) 22%, rgba(255,255,255,.08));
  border-radius: 9px; background: linear-gradient(180deg, rgba(14,12,7,.9), rgba(4,7,8,.98)); overflow: hidden;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.07); }
.app-shell-spectrum::before { content: ""; position: absolute; inset: 0;
  background:
    linear-gradient(112deg, transparent 0 40%, rgba(255,198,77,.08) 48%, rgba(46,232,214,.06) 54%, transparent 63%),
    repeating-linear-gradient(0deg, rgba(255,255,255,.026) 0 1px, transparent 1px 8px);
  transform: translateX(-96%); animation: passkey-sweep 6.4s var(--motion) infinite; pointer-events: none; }
.app-shell-spectrum > * { position: relative; z-index: 1; min-width: 0; }
.app-shell-spectrum__head { display: grid; grid-template-columns: minmax(150px, .8fr) minmax(0, 1.2fr); gap: 8px; align-items: end;
  padding: 8px; border-bottom: 1px solid rgba(255,255,255,.07); background: linear-gradient(90deg, rgba(255,198,77,.09), rgba(46,232,214,.055), rgba(159,124,255,.045)); }
.app-shell-spectrum__head div { display: grid; gap: 5px; min-width: 0; }
.app-shell-spectrum__head span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  color: var(--self); font: 900 8px/1 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: .08em; text-transform: uppercase; }
.app-shell-spectrum__head b { color: #f4fffb; font: 950 12px/1 ui-monospace, SFMono-Regular, Menlo, monospace; text-transform: uppercase; overflow-wrap: anywhere; }
.app-shell-spectrum__head p { margin: 0; color: #a8b7bd; font-size: 9px; line-height: 1.25; overflow-wrap: anywhere; }
.app-shell-spectrum__terminal { display: grid; grid-template-columns: minmax(0, 1fr); gap: 7px; padding: 8px; border-bottom: 1px solid rgba(255,255,255,.07);
  background: repeating-linear-gradient(0deg, rgba(255,255,255,.028) 0 1px, transparent 1px 8px); }
.app-shell-spectrum__terminal pre { margin: 0; color: #fff4c8; white-space: pre; overflow: auto;
  font: 900 7.3px/1.28 ui-monospace, SFMono-Regular, Menlo, monospace; text-shadow: 0 0 14px rgba(255,198,77,.18); }
.app-shell-spectrum__counters { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1px; background: rgba(255,255,255,.07); border-radius: 7px; overflow: hidden; }
