  font: 900 7.4px/1.08 ui-monospace, SFMono-Regular, Menlo, monospace; text-transform: uppercase; overflow-wrap: anywhere; }
.app-shell-spectrum__rails { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1px; background: rgba(255,255,255,.07); }
.app-shell-spectrum-rail { --tone: var(--brand-from, var(--accent)); --tone-2: var(--brand-to, var(--verified)); --brand-ink: #071013;
  position: relative; min-height: 158px; display: grid; grid-template-rows: auto 46px auto auto auto 1fr; gap: 6px; align-content: start;
  padding: 8px; color: inherit; background: radial-gradient(circle at 50% 0, color-mix(in srgb, var(--tone) 16%, transparent), transparent 40%),
    linear-gradient(145deg, color-mix(in srgb, var(--tone) 12%, #0b1115), #040708); overflow: hidden;
  animation: feed-rise .54s var(--motion) both; animation-delay: calc(var(--i) * 64ms); }
