.app-shell-spectrum-rail__top { display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 6px; align-items: center; }
.app-shell-spectrum-rail__top i { display: inline-grid; place-items: center; width: 28px; height: 26px; border-radius: 8px;
  color: var(--brand-ink); background: linear-gradient(135deg, var(--tone), var(--tone-2)); font: 900 9px/1 ui-monospace, SFMono-Regular, Menlo, monospace; font-style: normal; }
.app-shell-spectrum-rail__top span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #f4fffb;
  font: 950 8.4px/1.08 ui-monospace, SFMono-Regular, Menlo, monospace; text-transform: uppercase; }
.app-shell-spectrum-rail__bars { height: 46px; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); align-items: end; gap: 3px;
  padding: 5px; border: 1px solid color-mix(in srgb, var(--tone) 24%, rgba(255,255,255,.08)); border-radius: 8px;
  background: repeating-linear-gradient(0deg, rgba(255,255,255,.035) 0 1px, transparent 1px 7px), #040607; overflow: hidden; }
.app-shell-spectrum-rail__bars i { display: block; min-height: 5px; height: var(--bar); border-radius: 999px 999px 3px 3px;
  background: linear-gradient(180deg, var(--tone-2), var(--tone)); box-shadow: 0 0 14px color-mix(in srgb, var(--tone) 32%, transparent);
