.app-shell-spectrum-rail b { width: fit-content; color: var(--self); border: 1px solid color-mix(in srgb, var(--self) 30%, var(--line));
  border-radius: 999px; padding: 3px 6px; background: rgba(0,0,0,.2); font: 900 7.8px/1 ui-monospace, SFMono-Regular, Menlo, monospace; text-transform: uppercase; overflow-wrap: anywhere; }
