/* VibeUsage global instrument panel */
html, body {
  font-family: var(--font-display), ui-sans-serif, system-ui, sans-serif;
}

code, pre, .console-top {
  font-family: var(--font-data), ui-monospace, monospace;
}

.hdr {
  position: sticky;
  top: 0;
  z-index: 40;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  min-height: 66px;
  padding: 0 clamp(18px, 3vw, 44px);
  background: rgba(4, 7, 8, .88);
  border-bottom: 1px solid rgba(154, 247, 226, .12);
  box-shadow: 0 12px 40px rgba(0, 0, 0, .22);
  backdrop-filter: blur(18px) saturate(130%);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0;
  color: var(--fg);
  font: 700 18px/1 var(--font-data), ui-monospace, monospace;
  letter-spacing: 0;
  text-shadow: none;
}

.brand > i {
  width: 9px;
  height: 9px;
  margin-right: 10px;
  border: 2px solid #071013;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 1px var(--accent), 0 0 20px rgba(46, 232, 214, .5);
}

.brand span { color: #f4fffb; }
.brand strong { color: var(--accent); font-weight: 700; }

.hdr .hdr-primary {
  justify-self: center;
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 4px;
}

.hdr .hdr-primary a {
  padding: 8px 11px;
  color: #9eabb1;
  border: 0;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0;
}

.hdr .hdr-primary a:hover,
.hdr .hdr-primary a:focus-visible {
  color: #f4fffb;
  background: rgba(255, 255, 255, .05);
  transform: none;
}

.hdr-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.hdr-cli {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  padding: 0 14px;
  border: 1px solid rgba(46, 232, 214, .42);
  border-radius: 6px;
  color: #dffff8;
  background: rgba(46, 232, 214, .08);
  font: 600 11px/1 var(--font-data), ui-monospace, monospace;
  text-transform: uppercase;
  transition: background .2s ease, border-color .2s ease, transform .2s ease;
}

.hdr-cli:hover,
.hdr-cli:focus-visible {
  border-color: var(--accent);
  background: rgba(46, 232, 214, .14);
  transform: translateY(-1px);
}

.hdr-cli:active { transform: translateY(1px); }

.hdr-menu { position: relative; }
.hdr-menu > summary {
  width: 40px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, .11);
  border-radius: 6px;
  color: #dffff8;
  background: rgba(255, 255, 255, .03);
  cursor: pointer;
  list-style: none;
  transition: background .2s ease, border-color .2s ease, transform .2s ease;
}

.hdr-menu > summary::-webkit-details-marker { display: none; }
.hdr-menu > summary:hover,
.hdr-menu > summary:focus-visible,
.hdr-menu[open] > summary {
  border-color: rgba(46, 232, 214, .52);
  background: rgba(46, 232, 214, .1);
}
.hdr-menu > summary:active { transform: translateY(1px); }
.hdr-menu > summary > i { width: 17px; display: grid; gap: 4px; }
.hdr-menu > summary > i span { display: block; height: 1px; background: currentColor; }

.hdr-menu > nav {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  width: min(360px, calc(100vw - 28px));
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  padding: 7px;
  border: 1px solid rgba(46, 232, 214, .24);
  border-radius: 8px;
  background: rgba(7, 12, 14, .98);
  box-shadow: 0 24px 64px rgba(0, 0, 0, .5), inset 0 1px rgba(255, 255, 255, .05);
}

.hdr-menu > nav a {
  display: grid;
  grid-template-columns: 24px 1fr;
  gap: 8px;
  align-items: center;
  min-height: 42px;
  padding: 8px;
  color: #c2ced2;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 600;
}

.hdr-menu > nav a span {
  color: var(--accent);
  font: 500 9px/1 var(--font-data), ui-monospace, monospace;
}

.hdr-menu > nav a:hover,
.hdr-menu > nav a:focus-visible {
  color: #f4fffb;
  background: rgba(46, 232, 214, .08);
}

.app-shell-dock {
  display: block;
  max-width: 1280px;
  margin: 22px auto 0;
  padding: 0 clamp(14px, 3vw, 32px);
}

.wrap > .app-shell-dock {
  width: min(1280px, calc(100vw - 24px));
  max-width: none;
  margin: -12px 50% 34px;
  transform: translateX(-50%);
}

.usage-instrument {
  position: relative;
  display: grid;
  grid-template-columns: minmax(300px, .72fr) minmax(560px, 1.28fr);
  min-height: 350px;
  overflow: hidden;
  border: 1px solid rgba(124, 231, 208, .22);
  border-radius: 8px;
  background: #071013;
  box-shadow: 0 32px 90px rgba(0, 0, 0, .38), inset 0 1px rgba(255, 255, 255, .06);
}

.usage-instrument::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(rgba(255, 255, 255, .024) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .018) 1px, transparent 1px);
  background-size: 100% 8px, 32px 100%;
  opacity: .55;
}

.usage-instrument > * { position: relative; z-index: 1; min-width: 0; }

.usage-instrument__copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(28px, 4vw, 48px);
  border-right: 1px solid rgba(255, 255, 255, .08);
  background: linear-gradient(145deg, rgba(46, 232, 214, .09), transparent 52%);
}

.usage-instrument__kicker {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px 14px;
  margin-bottom: 23px;
}

.usage-instrument__kicker span,
.usage-instrument__kicker code {
  color: #95a7aa;
  border: 0;
  background: transparent;
  padding: 0;
  font: 600 9px/1 var(--font-data), ui-monospace, monospace;
  text-transform: uppercase;
}

.usage-instrument__kicker span { color: #a5f3dc; }
.usage-instrument__kicker i,
.usage-instrument__scope-head i {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 7px;
  border-radius: 50%;
  background: var(--verified);
  box-shadow: 0 0 14px rgba(54, 227, 155, .65);
}

.usage-instrument__title {
  margin: 0;
  max-width: 12ch;
  color: #f4fffb;
  font-size: clamp(32px, 3.2vw, 48px);
  font-weight: 600;
  line-height: .98;
  letter-spacing: 0;
  text-wrap: balance;
}

.usage-instrument__title span { color: var(--accent); }

.usage-instrument__lede {
  max-width: 42ch;
  margin: 19px 0 0;
  color: #a4b1b5;
  font-size: 14px;
  line-height: 1.55;
  text-wrap: pretty;
}

.usage-instrument__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 25px;
}

.usage-instrument__actions a {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 18px;
  padding: 0 14px;
  border: 1px solid rgba(255, 255, 255, .13);
  border-radius: 6px;
  color: #d7e4e2;
  font: 600 11px/1 var(--font-data), ui-monospace, monospace;
  transition: background .2s ease, border-color .2s ease, transform .2s ease;
}

.usage-instrument__actions a:first-child {
  color: #06100f;
  border-color: var(--accent);
  background: var(--accent);
}

.usage-instrument__actions a:hover,
.usage-instrument__actions a:focus-visible {
  border-color: var(--accent);
  transform: translateY(-1px);
}
.usage-instrument__actions a:first-child:hover,
.usage-instrument__actions a:first-child:focus-visible { background: #75f5e8; }
.usage-instrument__actions a:active { transform: translateY(1px); }

.usage-instrument__scope {
  min-width: 0;
  display: grid;
  grid-template-rows: 44px 1fr 38px;
  background: rgba(2, 6, 8, .58);
}

.usage-instrument__scope-head,
.usage-instrument__scope-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 0 17px;
  border-bottom: 1px solid rgba(255, 255, 255, .07);
}

.usage-instrument__scope-head div {
  display: flex;
  align-items: center;
  color: #dffaf3;
  font: 600 10px/1 var(--font-data), ui-monospace, monospace;
  text-transform: uppercase;
}

.usage-instrument__scope-head code {
  padding: 0;
  border: 0;
  color: #77868c;
  background: transparent;
  font-size: 9px;
}

.usage-instrument__channels { display: grid; grid-template-rows: repeat(5, minmax(54px, 1fr)); }

.usage-channel {
  --tone: var(--brand-from, var(--accent));
  --tone-2: var(--brand-to, var(--verified));
  position: relative;
  display: grid;
  grid-template-columns: minmax(138px, .8fr) minmax(160px, 1.3fr) minmax(120px, .9fr) 72px;
  gap: 14px;
  align-items: center;
  min-width: 0;
  padding: 8px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, .065);
  overflow: hidden;
  animation: instrument-channel-in .48s var(--motion) both;
  animation-delay: calc(var(--i) * 70ms);
}

.usage-channel::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 2px;
  background: var(--tone);
  box-shadow: 0 0 18px color-mix(in srgb, var(--tone) 45%, transparent);
}

.usage-channel:last-child { border-bottom: 0; }
.usage-channel__identity { display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: 9px; align-items: center; min-width: 0; }
.usage-channel__identity > i {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 6px;
  color: #06100f;
  background: var(--tone);
  font: 600 8px/1 var(--font-data), ui-monospace, monospace;
  font-style: normal;
}

.usage-channel__identity div { min-width: 0; display: grid; gap: 4px; }
.usage-channel__identity span,
.usage-channel__identity b {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-data), ui-monospace, monospace;
  letter-spacing: 0;
  text-transform: uppercase;
}
.usage-channel__identity span { color: #dffaf3; font-size: 9px; font-weight: 600; }
.usage-channel__identity b { color: var(--tone); font-size: 8px; font-weight: 500; }

.usage-channel__wave {
  height: 30px;
  display: grid;
  grid-template-columns: repeat(7, minmax(3px, 1fr));
  align-items: end;
  gap: 4px;
  padding: 3px 0;
  background: repeating-linear-gradient(0deg, transparent 0 6px, rgba(255, 255, 255, .045) 7px);
}

.usage-channel__wave i {
  min-height: 3px;
  height: var(--bar);
  border-radius: 2px 2px 0 0;
  background: linear-gradient(180deg, var(--tone-2), var(--tone));
  box-shadow: 0 0 11px color-mix(in srgb, var(--tone) 28%, transparent);
  transform-origin: bottom;
  animation: instrument-wave-in .65s var(--motion) both;
  animation-delay: calc(120ms + var(--i) * 45ms + var(--b) * 24ms);
}

.usage-channel > code {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 0;
  border: 0;
  color: #78888e;
  background: transparent;
  font-size: 8px;
}

.usage-channel > em {
  width: 72px;
  height: 3px;
  display: block;
  overflow: hidden;
  background: rgba(255, 255, 255, .08);
  font-style: normal;
}

.usage-channel > em i {
  display: block;
  width: var(--meter);
  height: 100%;
  background: var(--tone);
  transform-origin: left;
  animation: instrument-meter-in .7s var(--motion) both;
  animation-delay: calc(180ms + var(--i) * 60ms);
}

.usage-instrument__scope-foot {
  justify-content: flex-start;
  border-top: 1px solid rgba(255, 255, 255, .07);
  border-bottom: 0;
  color: #7f9095;
  font: 500 8px/1 var(--font-data), ui-monospace, monospace;
  text-transform: uppercase;
}

.usage-instrument__scope-foot span { display: inline-flex; align-items: center; gap: 6px; }
.usage-instrument__scope-foot span i { width: 5px; height: 5px; border-radius: 50%; background: var(--verified); }
.usage-instrument__scope-foot span:nth-child(2) i { background: var(--self); }
.usage-instrument__scope-foot span:nth-child(3) i { background: #a7ddd5; }
.usage-instrument__scope-foot strong { margin-left: auto; color: var(--accent); font-weight: 600; }

.app-shell-diagnostics {
  margin-top: 8px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 7px;
  background: rgba(5, 9, 11, .72);
}

.app-shell-diagnostics > summary {
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 13px;
  color: #93a3a8;
  cursor: pointer;
  list-style: none;
  font: 500 9px/1 var(--font-data), ui-monospace, monospace;
  text-transform: uppercase;
}
.app-shell-diagnostics > summary::-webkit-details-marker { display: none; }
.app-shell-diagnostics > summary::before { content: "+"; color: var(--accent); font-size: 14px; }
.app-shell-diagnostics[open] > summary::before { content: "-"; }
.app-shell-diagnostics > summary span { margin-right: auto; color: #d8e4e2; }
.app-shell-diagnostics > summary b { color: #718086; font-weight: 500; }
.usage-diagnostics {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 1px;
  padding: 8px;
  border-top: 1px solid rgba(255, 255, 255, .07);
  background: rgba(255, 255, 255, .045);
}
.usage-diagnostics article {
  --tone: var(--brand-from, var(--accent));
  min-width: 0;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 7px;
  align-content: start;
  padding: 10px;
  background: #071013;
}
.usage-diagnostics article > i {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 6px;
  color: #06100f;
  background: var(--tone);
  font: 600 8px/1 var(--font-data), ui-monospace, monospace;
  font-style: normal;
}
.usage-diagnostics article div { min-width: 0; display: grid; gap: 4px; }
.usage-diagnostics article span,
.usage-diagnostics article b {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-data), ui-monospace, monospace;
  text-transform: uppercase;
}
.usage-diagnostics article span { color: #e5f4f1; font-size: 9px; }
.usage-diagnostics article b { color: var(--tone); font-size: 8px; font-weight: 500; }
.usage-diagnostics article code,
.usage-diagnostics article small {
  grid-column: 1 / -1;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.usage-diagnostics article code { padding: 0; border: 0; color: #9eafb3; background: transparent; font-size: 8px; }
.usage-diagnostics article small { color: #68787e; font: 500 8px/1.3 var(--font-data), ui-monospace, monospace; }
.app-shell-diagnostics__body {
  display: grid;
  grid-template-columns: minmax(300px, .82fr) minmax(0, 1.18fr);
  gap: 1px;
  padding: 8px;
  border-top: 1px solid rgba(255, 255, 255, .07);
}
.app-shell-diagnostics__body .app-shell-dock__terminal { border-radius: 7px 0 0 7px; }
.app-shell-diagnostics__body .app-shell-signals { border-radius: 0 7px 7px 0; }

@keyframes instrument-channel-in {
  from { opacity: 0; transform: translateX(10px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes instrument-wave-in {
  from { transform: scaleY(.08); opacity: .25; }
  to { transform: scaleY(1); opacity: 1; }
}
@keyframes instrument-meter-in {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}

@media (max-width: 980px) {
  .hdr .hdr-primary { gap: 1px; }
  .hdr .hdr-primary a { padding-inline: 8px; font-size: 12px; }
  .usage-instrument { grid-template-columns: minmax(260px, .68fr) minmax(490px, 1.32fr); }
  .usage-instrument__copy { padding: 28px; }
  .usage-channel { grid-template-columns: minmax(118px, .75fr) minmax(130px, 1.2fr) 64px; gap: 10px; padding-inline: 12px; }
  .usage-channel > code { display: none; }
  .usage-diagnostics { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (max-width: 760px) {
  .hdr {
    grid-template-columns: minmax(0, 1fr) auto;
    min-height: 112px;
    padding: 12px 14px 0;
  }
  .hdr .brand { align-self: start; min-height: 38px; }
  .hdr-actions { align-self: start; }
  .hdr-cli { min-height: 36px; padding-inline: 11px; }
  .hdr .hdr-primary {
    grid-column: 1 / -1;
    grid-row: 2;
    align-self: end;
    justify-self: stretch;
    width: calc(100% + 28px);
    margin-left: -14px;
    padding: 0 10px 8px;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .hdr .hdr-primary::-webkit-scrollbar { display: none; }
  .hdr .hdr-primary a { flex: 0 0 auto; padding: 8px 9px; }
  .hdr-menu > nav { position: fixed; top: 62px; right: 14px; }
  .app-shell-dock { margin-top: 14px; padding-inline: 10px; }
  .usage-instrument { grid-template-columns: 1fr; min-height: 0; }
  .usage-instrument__copy {
    min-height: 250px;
    padding: 26px 22px 28px;
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, .08);
  }
  .usage-instrument__title { max-width: 13ch; font-size: 36px; }
  .usage-instrument__lede { margin-top: 14px; }
  .usage-instrument__actions { margin-top: 19px; }
  .usage-instrument__scope { grid-template-rows: 42px 1fr 34px; }
  .usage-instrument__channels { grid-template-rows: repeat(5, 52px); }
  .usage-channel { grid-template-columns: minmax(112px, .8fr) minmax(100px, 1fr) 58px; padding-inline: 11px; }
  .usage-channel__wave { gap: 3px; }
  .usage-channel > em { width: 58px; }
  .usage-instrument__scope-foot { overflow-x: auto; white-space: nowrap; }
  .usage-instrument__scope-foot strong { margin-left: 8px; }
  .app-shell-diagnostics > summary b { display: none; }
  .app-shell-diagnostics__body { grid-template-columns: 1fr; }
  .usage-diagnostics { grid-template-columns: 1fr; }
  .usage-diagnostics article { grid-template-columns: 28px minmax(0, 1fr) minmax(110px, .8fr); align-items: center; }
  .usage-diagnostics article code { grid-column: auto; }
  .usage-diagnostics article small { display: none; }
  .app-shell-diagnostics__body .app-shell-dock__terminal,
  .app-shell-diagnostics__body .app-shell-signals { border-radius: 7px; }
}

@media (max-width: 430px) {
  .hdr-cli { display: none; }
  .hdr { min-height: 108px; }
  .hdr .hdr-primary a { font-size: 11px; }
  .hdr-menu > nav { grid-template-columns: 1fr; max-height: calc(100dvh - 82px); overflow-y: auto; }
  .usage-instrument__copy { min-height: 232px; padding: 22px 17px 24px; }
  .usage-instrument__kicker { margin-bottom: 17px; }
  .usage-instrument__title { font-size: 32px; }
  .usage-instrument__lede { font-size: 13px; }
  .usage-instrument__actions a { min-height: 38px; padding-inline: 11px; }
  .usage-instrument__actions a:nth-child(2) { display: none; }
  .usage-instrument__scope-head code { display: none; }
  .usage-channel { grid-template-columns: 104px minmax(88px, 1fr) 48px; gap: 8px; padding-inline: 8px; }
  .usage-channel__identity { grid-template-columns: 26px minmax(0, 1fr); gap: 7px; }
  .usage-channel__identity > i { width: 26px; height: 26px; }
  .usage-channel > em { width: 48px; }
  .usage-instrument__scope-foot { padding-inline: 10px; gap: 10px; }
  .wrap > .app-shell-dock { width: calc(100vw - 12px); padding-inline: 6px; }
  .usage-diagnostics article { grid-template-columns: 26px minmax(0, 1fr); }
  .usage-diagnostics article code { grid-column: 1 / -1; }
}

@media (prefers-reduced-motion: reduce) {
  .usage-channel,
  .usage-channel__wave i,
  .usage-channel > em i { animation: none; transform: none; opacity: 1; }
}
